def validate_bank() -> dict:
    ids = [item["id"] for item in QUESTIONS]
    if len(ids) != len(set(ids)):
        duplicates = [key for key, count in Counter(ids).items() if count > 1]
        raise AssertionError(f"重复题号: {duplicates}")
    required = {"id", "chapter", "type", "topic", "prompt", "answer", "locator"}
    for item in QUESTIONS:
        missing = required - set(item)
        if missing:
            raise AssertionError(f"{item.get('id', '?')} 缺少字段: {sorted(missing)}")
        if not item["prompt"].strip() or not item["answer"] or not item["locator"].strip():
            raise AssertionError(f"{item['id']} 内容为空")
    chapter_counts = Counter(item["chapter"] for item in QUESTIONS)
    type_counts = Counter(item["type"] for item in QUESTIONS)
    for chapter, meta in CHAPTERS.items():
        actual = Counter(item["type"] for item in QUESTIONS if item["chapter"] == chapter)
        if dict(actual) != {k: v for k, v in meta["expected"].items() if v}:
            raise AssertionError(f"第{chapter}章配额错误: {dict(actual)}")
    expected_chapters = {1: 11, 2: 15, 3: 11, 5: 14, 6: 17}
    expected_types = {"填空题": 33, "简答题": 17, "问答题": 12, "计算题": 6}
    if dict(chapter_counts) != expected_chapters:
        raise AssertionError(f"章节数量错误: {dict(chapter_counts)}")
    if dict(type_counts) != expected_types:
        raise AssertionError(f"题型数量错误: {dict(type_counts)}")
    return {
        "questions": len(QUESTIONS),
        "answers": sum(bool(item["answer"]) for item in QUESTIONS),
        "chapters": dict(chapter_counts),
        "types": dict(type_counts),
    }


if __name__ == "__main__":
    print(validate_bank())
